import numpy as np
from pydrake.systems.framework import BasicVector, LeafSystem


class GRFEstimation(LeafSystem):
    def __init__(self, dt):
        super().__init__()
        self.dt = dt

        # Declare an output port 
        self.input_port_0 = self.DeclareVectorInputPort(
            "input_0",
            BasicVector(12)  
        )
        self.DeclareVectorOutputPort(
            "output_0",
            BasicVector(12),
            self.CalcOutput_0
        )
        # Declare periodic events
        self.DeclarePeriodicUnrestrictedUpdateEvent(period_sec=0.01                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ,
                                                    offset_sec=0.0,
                                                    update=self.UnrestrictedUpdate) 
        self.DeclarePeriodicDiscreteUpdateEvent(
            period_sec=self.dt,  
            offset_sec=0.0,  
            update=self.DiscreteUpdate)
        
    def UnrestrictedUpdate(self, context, state):
        # Update any type of state variables
        pass 

    def DiscreteUpdate(self, context, discrete_state):
        # Update discrete variables
        pass 

    def CalcOutput_0(self, context, output):
        out = np.zeros([1,12])
        output.SetFromVector(out[0])